using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(o,args);
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Toggle(System.Windows.Controls.Primitives.ToggleButton b,bool value){b.IsChecked=value;b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static Button FindButton(Window w,string text)=>Logical((DependencyObject)w.Content).OfType<Button>().Single(b=>b.Content as string==text);
    static T Named<T>(Window w,string name)where T:FrameworkElement=>Logical((DependencyObject)w.Content).OfType<T>().Single(e=>e.Name==name);
    static void Layout(Window w,double width,double height,string file){var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();foreach(var b in Logical(body).OfType<Button>().Where(b=>b.IsVisible||b.ActualWidth>0)){var point=b.TranslatePoint(new Point(),body);Check(point.X>=-1&&point.X+b.ActualWidth<=width+1,"Button clipped horizontally: "+b.Content);}var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle(w.Background,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
    static Package Second(MainWindow w,string dir){var p=Fixture(Path.Combine(dir,"second"));p.Alias="두 번째 가상 게임";Get<List<Package>>(w,"packages").Add(p);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",Get<List<Package>>(w,"packages").Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());return p;}
    static IntakeSelection Plan(MainWindow w,List<Package> games)=>new(new MoveSelection(games,Get<List<Package>>(w,"packages")));
    [STAThread]static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        Test("default-register-hides-move-settings",dir=>{var w=Window(dir,out var p);Window? dialog=null;try{dialog=(Window)Call(w,"BuildImportPlan",new List<Package>{p},Path.Combine(dir,"library"))!;var plan=(IntakeSelection)dialog.Tag;Check(plan.Moving.Count==0&&plan.Backup,"Import default changed");Check(Named<StackPanel>(dialog,"MoveSettings").Visibility==Visibility.Collapsed,"Move settings exposed initially");Check(FindButton(dialog,"실행 목록에 등록").IsEnabled,"Registration unavailable");Layout(dialog,840,480,Path.Combine(dir,"default.png"));Check(FindButton(dialog,"실행 목록에 등록").Focusable&&FindButton(dialog,"취소").IsCancel,"Focus/cancel unavailable");}finally{dialog?.Close();Close(w);}});
        Test("moving-reveals-settings-and-backup-toggle",dir=>{var w=Window(dir,out var p);Window? dialog=null;try{dialog=(Window)Call(w,"BuildImportPlan",new List<Package>{p},Path.Combine(dir,"library"))!;Click(Named<Button>(dialog,"MoveChoice"));var plan=(IntakeSelection)dialog.Tag;Check(plan.Moving.SetEquals(new[]{p.Id})&&Named<StackPanel>(dialog,"MoveSettings").Visibility==Visibility.Visible,"Move choice did not reveal settings");var backup=Named<System.Windows.Controls.Primitives.ToggleButton>(dialog,"BackupBeforeMove");Check(backup.IsChecked==true,"Backup not recommended by default");Toggle(backup,false);Check(!plan.Backup&&Logical((DependencyObject)dialog.Content).OfType<TextBlock>().Any(t=>t.Text=="백업 없이 이동합니다."),"No-backup result not explicit");Layout(dialog,840,720,Path.Combine(dir,"moving.png"));Click(Named<Button>(dialog,"UseHereChoice"));Check(plan.Moving.Count==0&&Named<StackPanel>(dialog,"MoveSettings").Visibility==Visibility.Collapsed,"Use-here did not hide move options");}finally{dialog?.Close();Close(w);}});
        Test("backup-choice-not-carried-to-next-operation",dir=>{var w=Window(dir,out var p);Window? a=null;Window? b=null;try{a=(Window)Call(w,"BuildMovePlan",new List<Package>{p},Path.Combine(dir,"library"))!;Toggle(Named<System.Windows.Controls.Primitives.ToggleButton>(a,"BackupBeforeMove"),false);a.Close();a=null;b=(Window)Call(w,"BuildMovePlan",new List<Package>{p},Path.Combine(dir,"library"))!;Check(((IntakeSelection)b.Tag).Backup,"No-backup choice persisted across operations");}finally{a?.Close();b?.Close();Close(w);}});
        Test("per-game-exception-and-bulk-reset",dir=>{var w=Window(dir,out var p);Window? dialog=null;try{var other=Second(w,dir);dialog=(Window)Call(w,"BuildImportPlan",new List<Package>{p,other},Path.Combine(dir,"library"))!;var exp=Logical((DependencyObject)dialog.Content).OfType<Expander>().Single(e=>e.Header as string=="게임별 설정");Check(!exp.IsExpanded,"Per-game settings expanded by default");exp.IsExpanded=true;var choose=Logical((DependencyObject)exp.Content).OfType<Button>().Where(b=>b.Content as string=="보관함으로 옮기기").Last();Click(choose);var plan=(IntakeSelection)dialog.Tag;Check(plan.Moving.SetEquals(new[]{other.Id}),"Exception affected all games");Check(FindButton(dialog,"등록하고 옮기기").IsEnabled,"Mixed action unclear or disabled");Layout(dialog,824,600,Path.Combine(dir,"mixed.png"));Click(Named<Button>(dialog,"MoveChoice"));Check(plan.Moving.Count==2,"Bulk choice left stale exceptions");Click(Named<Button>(dialog,"UseHereChoice"));Check(plan.Moving.Count==0,"Bulk reset left move choice");}finally{dialog?.Close();Close(w);}});
        Test("only-moving-owners-bring-their-related-content",dir=>{var w=Window(dir,out var p);try{var other=Second(w,dir);var content=Fixture(Path.Combine(dir,"content"));content.IsContent=true;Get<List<Package>>(w,"packages").Add(content);p.RelatedFolders.Add(new(){Id=content.Id,Source=content.Source,Name=content.Name});var plan=Plan(w,new(){p,other});plan.Moving.Add(other.Id);Check(plan.MoveItems(Path.Combine(dir,"library"),Get<List<Package>>(w,"packages")).All(g=>g.Id!=content.Id),"Nonmoving game's content moved");plan.SetAll(true);Check(plan.MoveItems(Path.Combine(dir,"library"),Get<List<Package>>(w,"packages")).Any(g=>g.Id==content.Id),"Moving owner's related content omitted");}finally{Close(w);}});
        Test("register-only-keeps-game-and-creates-no-backup",dir=>{var w=Window(dir,out var p);try{Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);var path=p.Source;var bytes=File.ReadAllBytes(Path.Combine(path,"Data","large.bin"));Wait((Task)Call(w,"ExecuteIntakeAsync",Plan(w,new(){p}),Path.Combine(dir,"library"))!);Check(p.Registered==true&&Directory.Exists(path)&&File.ReadAllBytes(Path.Combine(path,"Data","large.bin")).SequenceEqual(bytes),"Registration moved or modified game payload");Check(!Directory.Exists(Path.Combine(dir,"backups"))&&!Directory.Exists(Path.Combine(dir,"records")),"Registration created backup/move job");Check(LibraryStore.ReadIdentity(path)!=null,"Registration identity missing");}finally{Close(w);}});
        foreach(var backup in new[]{false,true})Test("mixed-register-and-real-move-"+backup,dir=>{var w=Window(dir,out var p);try{var other=Second(w,dir);Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);var original=other.Source;var plan=Plan(w,new(){p,other});plan.Moving.Add(other.Id);plan.Backup=backup;Wait((Task)Call(w,"ExecuteIntakeAsync",plan,Path.Combine(dir,"library"))!);Check(p.Registered==true&&Directory.Exists(p.Source),"Use-here game was moved");Check(!Directory.Exists(original)&&File.Exists(Path.Combine(other.Source,"Game.exe")),"Moving game did not physically move");var state=Get<OperationStatus>(w,"operationStatus");Check(state.Done==1&&!state.NeedsAttention&&state.WithoutBackup==!backup,"Mixed result wrong");Check(backup?new BackupEngine(Path.Combine(dir,"backups")).ListJobs().Count==1:!Directory.Exists(Path.Combine(dir,"backups")),"Backup choice not honored");}finally{Close(w);}});
        Test("existing-registration-is-not-duplicated",dir=>{var w=Window(dir,out var p);try{Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);Wait((Task)Call(w,"ExecuteIntakeAsync",Plan(w,new(){p}),Path.Combine(dir,"library"))!);var id=p.Id;Wait((Task)Call(w,"ExecuteIntakeAsync",Plan(w,new(){p}),Path.Combine(dir,"library"))!);Check(p.Id==id&&Get<List<Package>>(w,"packages").Count==1&&new LibraryStore(Path.Combine(dir,"library")).Load().Games.Count==1,"Existing game duplicated");}finally{Close(w);}});
        Test("selected-folder-scan-does-not-scan-other-saved-roots",dir=>{var w=Window(dir,out var p);try{var unexpected=Fixture(Path.Combine(dir,"unselected"));Set(w,"searchLocations",new List<SearchLocation>{new(){Path=dir}});Set(w,"snapshot",null);Wait((Task)Call(w,"ScanIntakeFolderAsync",p.SearchRoot)!);Check(Get<List<Package>>(w,"packages").All(g=>!GameScanner.Within(g.Source,Path.Combine(dir,"unselected"))),"Import scanned entire previous broad root");Check(Get<ScanSnapshot>(w,"snapshot").IsPartial,"Partial import marked full scan");}finally{Close(w);}});
        Test("partial-import-keeps-existing-outside-games",dir=>{var w=Window(dir,out var p);try{Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);Wait((Task)Call(w,"ExecuteIntakeAsync",Plan(w,new(){p}),Path.Combine(dir,"library"))!);var other=Fixture(Path.Combine(dir,"incoming"));Set(w,"snapshot",null);Wait((Task)Call(w,"ScanIntakeFolderAsync",other.SearchRoot)!);Check(Get<List<Package>>(w,"packages").Any(g=>g.Id==p.Id&&g.Registered==true),"Existing game lost during partial scan");Check(new LibraryStore(Path.Combine(dir,"library")).Load().Games.Single(g=>g.Id==p.Id).Status!="Missing","Unscanned game marked missing");}finally{Close(w);}});
        Test("result-actions-and-failure-separation",dir=>{var w=Window(dir,out _);Window? dialog=null;try{dialog=(Window)Call(w,"BuildIntakeResult",new List<IntakeResult>{new("a","가상 A","등록 완료"),new("b","가상 B","등록 실패")})!;Check(FindButton(dialog,"실행 목록에서 보기")!=null&&FindButton(dialog,"정리에서 확인")!=null,"Next actions absent");Check(Logical((DependencyObject)dialog.Content).OfType<TextBlock>().Any(t=>t.Text=="등록 실패"),"Failure hidden among successes");Layout(dialog,600,460,Path.Combine(dir,"result.png"));}finally{dialog?.Close();Close(w);}});
        Test("registration-denied-is-not-marked-success",dir=>{var w=Window(dir,out var p);try{Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);LibraryStore.EnsureIdentity(p.Source,p.Id);using(var held=File.Open(Path.Combine(p.Source,LibraryStore.MarkerName),FileMode.Open,FileAccess.Read,FileShare.None)){var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(_,_)=>{foreach(var dialog in Application.Current.Windows.OfType<AppDialog>().ToList())dialog.Close();};timer.Start();try{Wait((Task)Call(w,"ExecuteIntakeAsync",Plan(w,new(){p}),Path.Combine(dir,"library"))!);}finally{timer.Stop();}Check(p.Registered!=true&&p.ReviewState=="identity","Denied registration marked complete");}Check(File.Exists(Path.Combine(p.Source,"Game.exe"))&&!Directory.Exists(Path.Combine(dir,"backups")),"Registration failure moved or backed up data");}finally{Close(w);}});
        Test("problem-action-selects-the-failed-game",dir=>{var w=Window(dir,out var p);Window? dialog=null;try{var other=Second(w,dir);dialog=(Window)Call(w,"BuildIntakeResult",new List<IntakeResult>{new(p.Id,"성공 예시","등록 완료"),new(other.Id,"실패 예시","등록 실패")})!;Click(FindButton(dialog,"정리에서 확인"));Check(Get<HashSet<string>>(w,"organizeSelection").SetEquals(new[]{other.Id})&&Get<Package>(w,"selected").Id==other.Id,"Problem action did not select failed item");dialog=null;}finally{dialog?.Close();Close(w);}});
        Test("all-failed-result-does-not-claim-completion",dir=>{var w=Window(dir,out var p);Window? dialog=null;try{dialog=(Window)Call(w,"BuildIntakeResult",new List<IntakeResult>{new(p.Id,"가상 게임","등록 실패")})!;Check(!FindButton(dialog,"실행 목록에서 보기").IsEnabled,"All-failed result offered empty successful list");Check(!Logical((DependencyObject)dialog.Content).OfType<TextBlock>().Any(t=>t.Text=="가져오기를 완료했습니다."),"Failure claimed completion");}finally{dialog?.Close();Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
